create or replace function public.process_organization_export(p_request_id uuid) returns jsonb language plpgsql security definer set search_path = 'public', 'pg_catalog' as $$ declare v_org uuid; v_user uuid; v_from timestamptz; v_to timestamptz; v_result jsonb; begin select organization_id, requested_by, (metadata->>'from')::timestamptz, (metadata->>'to')::timestamptz into v_org, v_user, v_from, v_to from public.privacy_requests where id = p_request_id and request_type = 'EXPORT' and status = 'PENDING' and metadata->>'async' = 'true' for update; if v_org is null or v_user is null then raise exception 'Export request not found'; end if; perform set_config('request.jwt.claim.sub', v_user::text, true); select public.export_organization_data(v_org, v_from, v_to) into v_result; return v_result; end; $$;